import os
from typing import Any, Dict, List, Optional

from google.cloud import texttospeech


def list_voices_for_locale(
    locale: str,
    gender: Optional[texttospeech.SsmlVoiceGender] = None,
) -> List[Dict[str, Any]]:
    client = texttospeech.TextToSpeechClient()
    response = client.list_voices(language_code=locale)

    voices: List[Dict[str, Any]] = []
    for voice in response.voices:
        if gender is not None and voice.ssml_gender != gender:
            continue
        voices.append(
            {
                "name": voice.name,
                "language_codes": list(voice.language_codes),
                "ssml_gender": texttospeech.SsmlVoiceGender(voice.ssml_gender).name,
                "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
            }
        )
    return voices


def select_voice_for_locale(
    locale: str,
    preferred_name_substring: Optional[str] = None,
    gender: Optional[texttospeech.SsmlVoiceGender] = None,
) -> Dict[str, Any]:
    voices = list_voices_for_locale(locale, gender=gender)
    if not voices:
        raise ValueError(f"No Google Cloud Text-to-Speech voices found for locale: {locale}")

    if preferred_name_substring:
        needle = preferred_name_substring.lower()
        for voice in voices:
            if needle in voice["name"].lower():
                return voice

    exact_locale = [v for v in voices if locale in v["language_codes"]]
    if exact_locale:
        premium_markers = ("Neural2", "Studio", "Wavenet", "Chirp3-HD", "News")
        for marker in premium_markers:
            for voice in exact_locale:
                if marker.lower() in voice["name"].lower():
                    return voice
        return sorted(exact_locale, key=lambda v: v["name"])[0]

    return sorted(voices, key=lambda v: v["name"])[0]


def google_credentials_hint() -> str:
    return os.getenv("GOOGLE_APPLICATION_CREDENTIALS", "")
